void lesen(const std::string& s) {  // keine Kopie, nur lesen
    std::cout << s.size();
}

void aendern(std::string& s) {       // verändert Original
    s += "!";
}

void als_kopie(std::string s) {      // teuer bei großen Strings
    s += "?";
}

std::string text = "Hallo";
aendern(text);       // text = "Hallo!"
lesen(text);
std::cout << text;   // Hallo!
